#!/usr/bin/env bash
# Regenerates _templates-gallery.qmd, the auto-generated template listing
# included by templates.qmd.
#
# A repo is treated as a template if it has both a template.qmd file and a
# preview/ directory at its root (the convention documented in
# creating-templates.qmd). Templates are discovered from two places:
#
#   - every repo in the quarto-vitae GitHub org
#   - every "owner/repo" listed in templates.yml (for third-party templates)
#
# Results are cached in .cache/templates.json for CACHE_TTL seconds so that
# `quarto preview` doesn't refetch on every save. Delete the cache file, or
# set FORCE_REFRESH=1, to force a refresh.
#
# Requires: gh (authenticated: `gh auth login`), jq
set -euo pipefail

cd "$(dirname "$0")/.."

ORG="quarto-vitae"
OUT="_templates-gallery.qmd"
CONFIG="templates.yml"
CACHE=".cache/templates.json"
CACHE_TTL=1800 # seconds

command -v gh >/dev/null || { echo "generate-templates.sh: 'gh' is required" >&2; exit 1; }
command -v jq >/dev/null || { echo "generate-templates.sh: 'jq' is required" >&2; exit 1; }

mkdir -p "$(dirname "$CACHE")"

cache_age() {
  local now mtime
  now=$(date +%s)
  mtime=$(date -r "$CACHE" +%s 2>/dev/null || echo 0)
  echo $((now - mtime))
}

if [[ -f "$CACHE" && "${FORCE_REFRESH:-}" != "1" && $(cache_age) -lt "$CACHE_TTL" ]]; then
  cards=$(cat "$CACHE")
else
  echo "generate-templates.sh: fetching template list from GitHub..." >&2

  org_repos=$(gh api "orgs/$ORG/repos" --paginate --jq '.[].full_name')

  extra_repos=""
  if [[ -f "$CONFIG" ]]; then
    extra_repos=$(grep -E '^[[:space:]]*-[[:space:]]*[^[:space:]#]+/[^[:space:]#]+' "$CONFIG" \
      | sed -E 's/^[[:space:]]*-[[:space:]]*//; s/[[:space:]]*(#.*)?$//' || true)
  fi

  all_repos=$(printf '%s\n%s\n' "$org_repos" "$extra_repos" | grep -v '^[[:space:]]*$' | sort -u)

  cards="[]"
  while IFS= read -r full_name; do
    [[ -z "$full_name" ]] && continue
    owner="${full_name%%/*}"
    repo="${full_name#*/}"

    meta=$(gh api "repos/$full_name" 2>/dev/null) || { echo "  skip $full_name (not found)" >&2; continue; }
    branch=$(jq -r '.default_branch' <<<"$meta")

    tree=$(gh api "repos/$full_name/git/trees/$branch?recursive=1" 2>/dev/null) || { echo "  skip $full_name (no tree)" >&2; continue; }

    has_template=$(jq -r '[.tree[]? | select(.path=="template.qmd")] | length' <<<"$tree")
    has_preview=$(jq -r '[.tree[]? | select(.path=="preview" and .type=="tree")] | length' <<<"$tree")
    if [[ "$has_template" -lt 1 || "$has_preview" -lt 1 ]]; then
      continue
    fi

    images=$(jq -r --arg owner "$owner" --arg repo "$repo" --arg branch "$branch" \
      '[.tree[]? | select(.path | test("^preview/[^/]+\\.(png|jpe?g|svg|webp)$"; "i")) | .path]
       | sort
       | map("https://raw.githubusercontent.com/" + $owner + "/" + $repo + "/" + $branch + "/" + .)' \
      <<<"$tree")

    title=$(gh api "repos/$full_name/readme" -H "Accept: application/vnd.github.raw" 2>/dev/null \
      | grep -m1 -E '^#[[:space:]]' | sed -E 's/^#[[:space:]]+//' || true)
    [[ -z "$title" ]] && title="$repo"

    description=$(jq -r '.description // ""' <<<"$meta")
    html_url=$(jq -r '.html_url' <<<"$meta")
    official=false
    [[ "$owner" == "$ORG" ]] && official=true

    card=$(jq -n --arg title "$title" --arg repo "$full_name" --arg desc "$description" \
      --arg url "$html_url" --argjson images "$images" --argjson official "$official" \
      '{title:$title, repo:$repo, description:$desc, url:$url, images:$images, official:$official}')

    cards=$(jq --argjson c "$card" '. + [$c]' <<<"$cards")
    echo "  found $full_name" >&2
  done <<<"$all_repos"

  cards=$(jq 'sort_by([(.official | not), (.title | ascii_downcase)])' <<<"$cards")
  echo "$cards" > "$CACHE"
fi

n=$(jq 'length' <<<"$cards")
echo "generate-templates.sh: writing $OUT ($n templates)" >&2

{
  echo "<!-- Generated by scripts/generate-templates.sh. Do not edit by hand. -->"
  echo

  if [[ "$n" -eq 0 ]]; then
    echo "::: {.callout-warning}"
    echo "No templates were found. If this is unexpected, check that gh is"
    echo "authenticated and that templates.yml points at valid repos."
    echo ":::"
  else
    echo '```{=html}'
    echo '<div class="template-carousel" data-template-carousel>'
    echo '<button class="carousel-btn carousel-prev" type="button" aria-label="Previous template">&#8249;</button>'
    echo '<div class="carousel-track" tabindex="0">'

    # One slide per preview image, so templates with several styles (e.g.
    # latexcv) show each style as its own slide.
    jq -c '.[] | . as $t | (.images | if length == 0 then [null] else . end) | to_entries[] | {t: $t, image: .value}' <<<"$cards" \
    | while IFS= read -r slide; do
      title=$(jq -r '.t.title' <<<"$slide" | sed 's/&/\&amp;/g; s/</\&lt;/g; s/"/\&quot;/g')
      desc=$(jq -r '.t.description' <<<"$slide" | sed 's/&/\&amp;/g; s/</\&lt;/g; s/"/\&quot;/g')
      url=$(jq -r '.t.url' <<<"$slide")
      official=$(jq -r '.t.official' <<<"$slide")
      nimg=$(jq -r '.t.images | length' <<<"$slide")
      image=$(jq -r '.image // empty' <<<"$slide")

      # Templates with a single preview have no style name, so use a
      # generic label.
      style="CV"
      if [[ "$nimg" -gt 1 && -n "$image" ]]; then
        style=$(basename "$image"); style="${style%.*}"
        style=$(printf '%s' "$style" | sed -E 's/[-_]+/ /g' | awk '{print (length($0)<=2) ? toupper($0) : toupper(substr($0,1,1)) substr($0,2)}')
      fi

      echo '<figure class="carousel-slide">'
      [[ -n "$image" ]] && echo "<a href=\"${url}\"><img class=\"template-preview\" src=\"${image}\" alt=\"${title}$([[ "$nimg" -gt 1 ]] && echo " ($style)") preview\" loading=\"lazy\"></a>"
      echo '<figcaption>'
      echo -n "<h4><a href=\"${url}\">${title}</a>"
      [[ "$official" != "true" ]] && echo -n ' <span class="template-badge">community</span>'
      echo '</h4>'
      echo "<p class=\"carousel-style\">${style}</p>"
      [[ -n "$desc" ]] && echo "<p>${desc}</p>"
      echo '</figcaption>'
      echo '</figure>'
    done

    echo '</div>'
    echo '<button class="carousel-btn carousel-next" type="button" aria-label="Next template">&#8250;</button>'
    echo '</div>'
    cat <<'JS'
<script>
document.querySelectorAll("[data-template-carousel]").forEach(function (c) {
  var track = c.querySelector(".carousel-track");
  function step(dir) {
    var slide = track.querySelector(".carousel-slide");
    var w = slide.getBoundingClientRect().width + 24;
    var atEnd = track.scrollLeft + track.clientWidth >= track.scrollWidth - 4;
    if (dir > 0 && atEnd) track.scrollTo({ left: 0, behavior: "smooth" });
    else if (dir < 0 && track.scrollLeft <= 4) track.scrollTo({ left: track.scrollWidth, behavior: "smooth" });
    else track.scrollBy({ left: dir * w, behavior: "smooth" });
  }
  c.querySelector(".carousel-prev").addEventListener("click", function () { step(-1); });
  c.querySelector(".carousel-next").addEventListener("click", function () { step(1); });

  // Slow continuous auto-scroll on the landing page only. Pauses while the
  // pointer, focus or a touch is on the carousel, and is skipped entirely
  // for people who prefer reduced motion.
  if (!c.closest(".landing-templates")) return;
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  var SPEED = 30; // pixels per second
  var paused = false, pos = 0, last = null;
  function setPaused(p) {
    paused = p;
    last = null;
    if (!p) pos = track.scrollLeft;
  }
  function tick(t) {
    if (!paused) {
      if (last !== null) {
        pos += SPEED * (t - last) / 1000;
        var max = track.scrollWidth - track.clientWidth;
        if (pos >= max) pos = 0;
        track.scrollLeft = pos;
      }
      last = t;
    }
    requestAnimationFrame(tick);
  }
  ["mouseenter", "focusin", "touchstart"].forEach(function (e) {
    c.addEventListener(e, function () { setPaused(true); }, { passive: true });
  });
  ["mouseleave", "focusout", "touchend"].forEach(function (e) {
    c.addEventListener(e, function () { setPaused(false); }, { passive: true });
  });
  // Keep scroll snapping off for good: re-enabling it on pause would snap
  // the track back to the nearest card edge.
  track.classList.add("is-auto");
  setPaused(false);
  requestAnimationFrame(tick);
});
</script>
JS
    echo '```'
  fi
} >"$OUT"
